class ResourceHolder {
    int* ptr_; // Resource to manage
public:
    // Required context setup
    ResourceHolder() : ptr_(nullptr) {}
    ~ResourceHolder() { delete ptr_; }

    // Move Assignment Operator
    ResourceHolder& operator=(ResourceHolder&& other) noexcept {
        if (this == &other) return *this;

        delete ptr_;          // 1. Release own resources

        ptr_ = other.ptr_;    // 2. Steal resources
        other.ptr_ = nullptr; // 3. Nullify source

        return *this;
    }
};
